import "core-js/modules/es.array.push.js";
/* eslint-disable */

import { formatedatetime } from "@/JsonFiles/DateFormate.js";
import { GChart } from "vue-google-charts/legacy";
import { expense_reports_graph, list_all_reports } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
import ExpenseGenerate from "@/components/ExpensesManagement/ExpensePopups/ExpenseGenerate.vue";
const FileSaver = require("file-saver");
import axios from "axios";
export default {
  components: {
    GChart,
    SnackBar,
    ExpenseGenerate
  },
  data: () => ({
    chartData1: [["labels", "Data"]],
    chartOptions: {
      // width:
      height: 250
    },
    date1: ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"][Number(new Date().toISOString().split("T")[0].split("-")[1]) - 1] + " " + new Date().toISOString().split("T")[0].split("-")[0],
    date: new Date().toISOString().substr(0, 7),
    height: 0,
    monthdailog: false,
    fixed: true,
    buttonload: false,
    tableData: [],
    SnackBarComponent: {},
    reportexpense: false,
    headers: [{
      title: "Month/Year",
      value: "report_year",
      sortable: false
    }, {
      title: "Generated On",
      value: "report_created_on",
      sortable: false
    }, {
      title: "Generated By",
      value: "report_created_by",
      sortable: false
    }, {
      title: "Status",
      value: "report_generation_status",
      sortable: false
    }, {
      title: "Actions",
      value: "actions",
      sortable: false
    }],
    tableLoading: false,
    formattedmonth: null,
    formattedyear: null,
    compenetCheck: 0,
    graphdata: [],
    total_amount_approved: "",
    total_amount_pending: "",
    total_amount_rejected: "",
    total_amount_withdrawn: "",
    currentPage: 1,
    itemsPerPage: 10
  }),
  computed: {
    totalItems() {
      return this.tableData.length;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    sortedAndPaginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  async created() {
    this.height = window.innerHeight - 360;
    await this.fecth_date();
    // await this.get_initiated_expense();
    await this.list_reports();
  },
  watch: {
    date(val) {
      this.date1 = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"][Number(val.split("-")[1]) - 1] + " " + val.split("-")[0];
    }
  },
  methods: {
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.reportexpense = false;
      this.list_reports();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async download_item(item) {
      let firstName = this.$store.getters.GetUserObj?.organization?.organization_team_id;
      let fileName = firstName ? firstName + "_" + (item.project_name == undefined ? item.group_name == undefined ? "All" : item.group_name : item.project_name) + "_" + (item.category_name == undefined ? "All" : item.category_name) + ".xlsx" : "_" + (item.project_name == undefined ? item.group_name == undefined ? "All" : item.group_name : item.project_name) + "_" + (item.category_name == undefined ? "All" : item.category_name) + ".xlsx";
      axios({
        url: item.report_url,
        method: "GET",
        responseType: "blob" // Set the response type to blob
      }).then(response => {
        const blob = new Blob([response.data], {
          type: response.headers["content-type"]
        });

        // Use the FileSaver library to save the file
        FileSaver.saveAs(blob, fileName);
      }).catch(error => {
        console.error("Error downloading the file:", error);
      });
    },
    month_year(report_year, report_month) {
      const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
      if (report_month >= 1 && report_month <= 12) {
        const formattedMonth = monthNames[report_month - 1];
        const formattedDate = `${formattedMonth}-${report_year}`;
        return formattedDate;
      } else {
        return "Invalid month";
      }
    },
    fetch_value(val) {
      return formatedatetime(val);
      // const d = new Date(parseInt(val * 1000));
      // var date = d.getDate().toLocaleString();
      // var month = (d.getMonth() + 1).toLocaleString();
      // var year = d.getFullYear();

      // return (
      //   (+date <= 9 ? "0" + date : date) +
      //   "/" +
      //   (+month <= 9 ? "0" + month : month) +
      //   "/" +
      //   year
      // );
    },
    async get_next() {
      this.chartData1 = [];
      this.chartData1 = [["labels", "Data"]];
      await this.fecth_date();
      await this.get_initiated_expense();
    },
    fecth_date() {
      const [month, year] = this.date1.split(" ");
      const monthMap = {
        January: "01",
        February: "02",
        March: "03",
        April: "04",
        May: "05",
        June: "06",
        July: "07",
        August: "08",
        September: "09",
        October: "10",
        November: "11",
        December: "12"
      };
      this.formattedmonth = `${monthMap[month]}`;
      this.formattedyear = `${year}`;
      this.formattedmonth = parseInt(this.formattedmonth, 10);
      this.formattedyear = parseInt(this.formattedyear, 10);
    },
    async list_reports() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_all_reports, {
          input: {
            organization_id: data.organization.organization_id,
            report_type: "EXPENSE"
          }
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.list_all_reports);
        if (response.Status == "SUCCESS") {
          this.tableData = response.data;
        }
        // console.log(response.data);
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    generatereport() {
      this.compenetCheck = 1;
      this.reportexpense = true;
    },
    async get_initiated_expense() {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(expense_reports_graph, {
          input: {
            organization_id: data.organization.organization_id,
            year: this.formattedyear,
            month: this.formattedmonth
          }
        }));
        var response = JSON.parse(result.data.expense_reports_graph).data;
        this.graphdata = response.expense_category_list;
        for (let i = 0; i < this.graphdata.length; i++) {
          this.chartData1.push([this.graphdata[i].expense_name, this.graphdata[i].total_amount]);
        }
        // console.log(this.chartData1, "this.chartData1");
        this.total_amount_approved = response.total_amount_approved;
        this.total_amount_pending = response.total_amount_pending;
        this.total_amount_rejected = response.total_amount_rejected;
        this.total_amount_withdrawn = response.total_amount_withdrawn;
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    handleSortChange() {
      // Implement sorting logic if needed
    },
    getStatusColor(status) {
      switch (status) {
        case "COMPLETED":
          return "green";
        case "IN PROGRESS":
          return "orange";
        default:
          return "grey";
      }
    },
    getStatusIcon(status) {
      switch (status) {
        case "COMPLETED":
          return "mdi-check-circle";
        case "IN PROGRESS":
          return "mdi-clock-outline";
        default:
          return "mdi-help-circle";
      }
    },
    getStatusTextColor(status) {
      switch (status) {
        case "COMPLETED":
          return "green--text";
        case "IN PROGRESS":
          return "orange--text";
        default:
          return "grey--text";
      }
    }
  }
};
